package technology.tabula.rate;

import java.text.Normalizer;
import java.util.Collections;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;

/**
 * Column-name conventions shared by the extracted waybill tables and the
 * external rate CSV.
 *
 * <p>Columns are matched by name. The Chinese names are the canonical ones;
 * a few common English spellings are accepted as aliases so the feature also
 * works with exports generated by other systems.</p>
 */
public final class RateColumns {

    /** Canonical name of the validity start column in the rate CSV. */
    public static final String EFFECTIVE = "生效日";
    /** Canonical name of the validity end column in the rate CSV. */
    public static final String EXPIRY = "失效日";
    /** Canonical name of the rate column in the rate CSV. */
    public static final String RATE = "费率";
    /** Canonical name of the shipment date column in the extracted table. */
    public static final String SHIPMENT_DATE = "运送日期";
    /** Typical join-key column of a waybill export (lane). */
    public static final String LANE = "线路";
    /** Typical join-key column of a waybill export (billing band). */
    public static final String BILLING_BAND = "计费档";

    private static final Set<String> EFFECTIVE_ALIASES = unmodifiable(
            EFFECTIVE, "生效日期", "有效起始日", "有效开始日",
            "effective_date", "effective", "valid_from", "start_date");

    private static final Set<String> EXPIRY_ALIASES = unmodifiable(
            EXPIRY, "失效日期", "有效截止日", "有效结束日",
            "expiry_date", "expiry", "expiration_date", "expires", "valid_to", "end_date");

    private static final Set<String> RATE_ALIASES = unmodifiable(
            RATE, "单价", "运价", "rate", "freight_rate", "price");

    private static final Set<String> SHIPMENT_DATE_ALIASES = unmodifiable(
            SHIPMENT_DATE, "运输日期", "发运日期", "发货日期", "承运日期",
            "ship_date", "shipment_date", "delivery_date", "transport_date");

    private RateColumns() {
    }

    private static Set<String> unmodifiable(String... names) {
        Set<String> set = new HashSet<>();
        for (String name : names) {
            set.add(normalizeName(name));
        }
        return Collections.unmodifiableSet(set);
    }

    /**
     * Normalizes a CSV/PDF cell or header: strips a UTF-8 byte-order mark,
     * applies NFKC and trims surrounding whitespace.
     */
    public static String normalize(String value) {
        if (value == null) {
            return "";
        }
        String s = value;
        if (!s.isEmpty() && s.charAt(0) == '﻿') {
            s = s.substring(1);
        }
        s = Normalizer.normalize(s, Normalizer.Form.NFKC);
        return s.trim();
    }

    /** Normalization used when comparing header names (case-insensitive). */
    public static String normalizeName(String value) {
        return normalize(value).toLowerCase(Locale.ROOT);
    }

    public static boolean isEffectiveColumn(String header) {
        return EFFECTIVE_ALIASES.contains(normalizeName(header));
    }

    public static boolean isExpiryColumn(String header) {
        return EXPIRY_ALIASES.contains(normalizeName(header));
    }

    public static boolean isRateColumn(String header) {
        return RATE_ALIASES.contains(normalizeName(header));
    }

    public static boolean isShipmentDateColumn(String header) {
        return SHIPMENT_DATE_ALIASES.contains(normalizeName(header));
    }

    /** True when the name is reserved by the rate CSV format (not a join key). */
    public static boolean isReservedColumn(String header) {
        return isEffectiveColumn(header) || isExpiryColumn(header)
                || isRateColumn(header) || isShipmentDateColumn(header);
    }

    static boolean sameName(String a, String b) {
        return normalizeName(a).equals(normalizeName(b));
    }
}
